// Command nexus-bench deploys, provisions, inspects and destroys the disposable
// Nexus Community bench of DEVDESK-504 on a k0s cluster. It is a development
// tool driven by the mise tasks nexus-bench:*, outside mise run ci; see
// docs/architecture/nexus-bench.md.
package main

import (
	"context"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"os/signal"
	"syscall"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// Exit codes.
const (
	exitOK      = 0
	exitFailure = 1
	exitUsage   = 2
)

// deps is everything the command needs that reaches a cluster or the network,
// so that the tests run it with fakes. The zero value is enough for render,
// which uses none of it.
type deps struct {
	newRunner  func(kubeContext string) (nexusbench.Runner, error)
	newProber  func() nexusbench.Prober
	clock      nexusbench.Clock
	newStore   func(path string) (nexusbench.SecretStore, error)
	newInitial func(r nexusbench.Runner, namespace string) nexusbench.InitialPassword
	preflight  func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params, op nexusbench.Op) (nexusbench.PreflightResult, error)
	deploy     func(ctx context.Context, r nexusbench.Runner, pr nexusbench.Prober, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) (nexusbench.DeployResult, error)
	provision  func(ctx context.Context, baseURL string, ip nexusbench.InitialPassword, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, error)
	destroy    func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, store nexusbench.SecretStore, p nexusbench.Params, out io.Writer) error

	// NX-02a (DEVDESK-544): the doors of the seed and the reads of status.
	newForwarder   func(kubeContext string) (nexusbench.PortForwarder, error)
	newCopier      func() (nexusbench.ImageCopier, error)
	ensureUpstream func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) error
	seed           func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) (nexusbench.SeedResult, error)
	readUpstream   func(ctx context.Context, r nexusbench.Runner, p nexusbench.Params) (nexusbench.UpstreamState, error)
	readImages     func(ctx context.Context, baseURL, repository string) ([]listedImage, error)

	// NX-02b (DEVDESK-534).
	cutUpstream     func(ctx context.Context, r nexusbench.Runner, clk nexusbench.Clock, p nexusbench.Params, out io.Writer) error
	restoreUpstream func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) error
	reset           func(ctx context.Context, d nexusbench.SeedDeps, baseURL string, p nexusbench.Params, out io.Writer) (nexusbench.ProvisionResult, nexusbench.SeedResult, error)
	unblockProxy    func(ctx context.Context, store nexusbench.SecretStore, baseURL string, p nexusbench.Params, out io.Writer) error
}

// defaultDeps wires the real kubectl, HTTP client, clock and files.
func defaultDeps() deps {
	return deps{
		newRunner:  nexusbench.NewExecRunner,
		newProber:  nexusbench.NewProber,
		clock:      nexusbench.NewClock(),
		newStore:   nexusbench.NewFileStore,
		newInitial: nexusbench.NewKubectlInitialPassword,
		preflight:  nexusbench.RunPreflight,
		deploy:     nexusbench.Deploy,
		provision:  nexusbench.Provision,
		destroy:    nexusbench.Destroy,

		newForwarder:   nexusbench.NewExecPortForwarder,
		newCopier:      nexusbench.NewSkopeoCopier,
		ensureUpstream: nexusbench.EnsureUpstream,
		seed:           nexusbench.Seed,
		readUpstream:   nexusbench.ReadUpstream,
		readImages:     readImagesAnonymously,

		cutUpstream:     nexusbench.CutUpstream,
		restoreUpstream: nexusbench.RestoreUpstream,
		reset:           nexusbench.Reset,
		unblockProxy:    nexusbench.UnblockProxy,
	}
}

func main() {
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	// After the first signal cancels ctx, hand the signals back to the default
	// behavior so that a second Ctrl-C kills a run that is slow to wind down.
	context.AfterFunc(ctx, stop)
	code := run(ctx, os.Args[1:], os.Getenv, os.Stdout, os.Stderr, defaultDeps())
	stop()
	os.Exit(code)
}

// session is one subcommand being run: its context, its resolved parameters and
// its streams.
type session struct {
	ctx    context.Context
	p      nexusbench.Params
	getenv func(string) string
	stdout io.Writer
	stderr io.Writer
	d      deps
	// restHost is where the REST API is reached; explicit tells whether the
	// operator chose it.
	restHost string
	explicit bool
}

// run executes one command line and returns the exit code: 0 for success, 1
// for a failure of the bench, 2 for a mistake in the command line.
func run(ctx context.Context, args []string, getenv func(string) string, stdout, stderr io.Writer, d deps) int {
	if len(args) == 0 {
		printUsage(stderr)
		return exitUsage
	}
	name := args[0]
	switch name {
	case "-h", "--help", "help":
		printUsage(stdout)
		return exitOK
	case "up", "provision", "down", "seed", "status", "render", "cut-upstream", "restore-upstream", "reset":
	default:
		_, _ = fmt.Fprintf(stderr, "nexus-bench: unknown subcommand %q\n\n", name)
		printUsage(stderr)
		return exitUsage
	}

	flags := newFlagSet(name)
	if err := flags.parse(args[1:]); err != nil {
		if errors.Is(err, flag.ErrHelp) {
			printSubcommandHelp(stdout, name, flags)
			return exitOK
		}
		_, _ = fmt.Fprintf(stderr, "nexus-bench %s: %v\nRun nexus-bench %s -h for the flags.\n", name, err, name)
		return exitUsage
	}

	s := &session{ctx: ctx, getenv: getenv, stdout: stdout, stderr: stderr, d: d, restHost: loopbackHost}
	p, err := flags.resolveParams(getenv)
	if err != nil {
		return s.fail(err)
	}
	s.p = p
	if host, given := flags.restHostGiven(); given {
		if err := validateRESTHost(host); err != nil {
			return s.fail(err)
		}
		if (name == "seed" && !isLoopbackHost(host)) || (loopbackOnly(name) && !nexusbench.IsLoopbackRESTHost(host)) {
			return s.fail(fmt.Errorf("%s always reaches Nexus and copies the images through 127.0.0.1, so --rest-host must be a loopback address", name))
		}
		s.restHost, s.explicit = host, true
	}

	switch name {
	case "up":
		return s.up()
	case "provision":
		return s.provision()
	case "down":
		return s.down()
	case "seed":
		return s.seed()
	case "status":
		return s.status()
	case "cut-upstream":
		return s.cutUpstream()
	case "restore-upstream":
		return s.restoreUpstream()
	case "reset":
		return s.reset()
	default:
		return s.render()
	}
}

// fail prints err on stderr and returns the failure code. A BenchError (also
// when wrapped or joined) is printed as its own message and nothing else: the
// text around it and the error it wraps can carry what a sub-process printed,
// a credential included. A cancelled run says so.
func (s *session) fail(err error) int {
	var be *nexusbench.BenchError
	switch {
	case errors.As(err, &be):
		_, _ = fmt.Fprintln(s.stderr, be.Error())
	case errors.Is(err, context.Canceled):
		_, _ = fmt.Fprintln(s.stderr, "cancelled; the cluster keeps what was already done, run nexus-bench status to see it")
	default:
		_, _ = fmt.Fprintln(s.stderr, err.Error())
	}
	return exitFailure
}

// warn prints a warning on stderr.
func (s *session) warn(format string, args ...any) {
	_, _ = fmt.Fprintf(s.stderr, "warning: "+format+"\n", args...)
}

// restURL is the REST origin the credentials are sent to.
func (s *session) restURL() string {
	return nexusbench.RESTBaseURL(s.restHost, s.p)
}

// warnIfClearText says so when the admin credentials leave this machine.
func (s *session) warnIfClearText() {
	if s.explicit && !isLoopbackHost(s.restHost) {
		s.warn("%s is plain HTTP: the credentials travel in clear text to %s", s.restURL(), s.restHost)
	}
}
package main

import (
	"fmt"
	"io"
)

const usageText = `nexus-bench: a disposable Nexus Community bench on a k0s cluster (DEVDESK-504)

Usage: nexus-bench <subcommand> [flags]

Subcommands:
  up         check the cluster, deploy the bench and its upstream registry, wait
             for Nexus, provision it, put docker-proxy back in service when the
             upstream was cut, seed the data set with skopeo and write the
             descriptor
  provision  provision a running Nexus again (idempotent) and write the descriptor
  down       delete the bench namespace and wait until it is gone
  seed       put the data set in a bench that up provisioned (needs skopeo on
             this machine, which mise does not install) and write the descriptor
  status     read the cluster and say how the bench is doing: pod, REST, upstream,
             descriptor, data set (changes nothing)
  render     print the manifests (contacts nothing)
  cut-upstream      scale the bench upstream to zero replicas and wait until no pod
                    is left, so the proxy can only serve what it cached (changes
                    nothing else; no descriptor)
  restore-upstream  bring the upstream back, put the proxy back in service and check
                    the images against the data set (needs skopeo on this machine)
  reset      delete docker-group, docker-proxy, docker-hosted and the upstream
             storage, then provision and seed again: the data set is back to its
             initial state, the pod, the namespace and the passwords are kept
             (needs skopeo on this machine)
  help       print this text

Run nexus-bench <subcommand> -h for the flags of a subcommand. Every flag has a
NEXUS_BENCH_* variable; a flag beats its variable, which beats the default.

Through mise: mise run nexus-bench:up -- --namespace nexus-bench-2

The EULA of Nexus Community Edition is accepted only when you say so
(--accept-eula or NEXUS_BENCH_ACCEPT_EULA=yes); read it first.

Exit codes: 0 success, 1 failure (the cause and what to check are on stderr),
2 mistake in the command line. go run (so mise run nexus-bench:*) does not pass
the code on: it prints "exit status 2" and exits 1. Code 2 is only visible when
the compiled binary is run directly (go build ./internal/nexusbench/cmd/nexus-bench).
`

// printUsage writes the general help to w.
func printUsage(w io.Writer) {
	_, _ = io.WriteString(w, usageText)
}

// subcommandSummary is the line each subcommand help starts with.
var subcommandSummary = map[string]string{
	"up":               "Check the cluster, deploy the bench and its upstream, wait for Nexus, provision it, put docker-proxy back in service when the upstream was cut, seed the data set and write the descriptor. Seeding needs skopeo on this machine (mise does not install it) unless NEXUS_BENCH_UPSTREAM_URL points at an upstream of your own.",
	"provision":        "Provision a running Nexus again (idempotent) and write the descriptor.",
	"down":             "Delete the bench namespace, wait until it is gone, then remove its stored passwords.",
	"seed":             "Put the data set in a bench that up provisioned (images in docker-hosted and in the upstream, one pulled through docker-proxy) and write the descriptor. Needs skopeo on this machine; mise does not install it.",
	"status":           "Read the cluster and the descriptor and report the pod, REST, upstream and data set; nothing is changed.",
	"render":           "Print the manifests for these parameters; the cluster is not contacted.",
	"cut-upstream":     "Scale the bench upstream to zero replicas and wait until no pod of it is left: the proxy then serves only what it cached. Nothing else is changed and the descriptor is not written.",
	"restore-upstream": "Bring the upstream back to one ready replica, put docker-proxy back in service (its configuration is sent again and its cache invalidated) and check the images of the upstream and the cached ones against the data set. Needs skopeo on this machine; mise does not install it.",
	"reset":            "Bring the data set back to its initial state without recreating the instance: delete docker-group, docker-proxy and docker-hosted and replace the claim bench-upstream-data, then provision and seed again and write the descriptor. The Nexus pod, nexus-data, the namespace and the stored passwords are kept. Needs skopeo on this machine; mise does not install it.",
}

// printSubcommandHelp writes the help of one subcommand to w.
func printSubcommandHelp(w io.Writer, name string, flags *flagSet) {
	_, _ = fmt.Fprintf(w, "Usage: nexus-bench %s [flags]\n\n%s\n\nA flag beats its NEXUS_BENCH_* variable, which beats the default.\n\nFlags:\n", name, subcommandSummary[name])
	flags.printHelp(w)
}
package main

import (
	"flag"
	"fmt"
	"io"
	"net/netip"
	"regexp"
	"strings"
	"time"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// Defaults of the flags that are not a NEXUS_BENCH_* parameter.
const (
	loopbackHost = "127.0.0.1"
	maxHostLen   = 253
)

var (
	// hostName is a DNS name: letters, digits, '.' and '-', no port, no path,
	// no credentials, no whitespace.
	hostName = regexp.MustCompile(`^[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?$`)
	// ipv6Zone is the zone of a link-local address ("eth0" in fe80::1%eth0).
	ipv6Zone = regexp.MustCompile(`^[A-Za-z0-9._-]+$`)
)

// flagKind is the type of a flag, which decides how it is registered and how
// its value is handed to nexusbench.FromEnv.
type flagKind int

const (
	kindString flagKind = iota
	kindInt
	kindDuration
	kindBool
	// kindConsent is a boolean whose true is the exact word "yes", the only
	// value nexusbench accepts for NEXUS_BENCH_ACCEPT_EULA.
	kindConsent
)

// paramFlag is one flag that stands for one NEXUS_BENCH_* variable.
type paramFlag struct {
	name  string
	env   string
	kind  flagKind
	usage string
}

// commonFlags are accepted by every subcommand.
func commonFlags() []paramFlag {
	d := nexusbench.Defaults()
	return []paramFlag{
		{"context", "NEXUS_BENCH_CONTEXT", kindString, "kubectl context of the cluster (default " + d.Context + ")"},
		{"namespace", "NEXUS_BENCH_NAMESPACE", kindString, "namespace of the bench, which down deletes (default " + d.Namespace + ")"},
		{"http-nodeport", "NEXUS_BENCH_HTTP_NODEPORT", kindInt, fmt.Sprintf("NodePort of the REST API and the UI (default %d)", d.HTTPNodePort)},
		{"docker-nodeport", "NEXUS_BENCH_DOCKER_NODEPORT", kindInt, fmt.Sprintf("NodePort of the Docker connector (default %d)", d.DockerNodePort)},
		{"cpu-request", "NEXUS_BENCH_CPU_REQUEST", kindString, "CPU request (default " + d.CPURequest + ")"},
		{"cpu-limit", "NEXUS_BENCH_CPU_LIMIT", kindString, "CPU limit (default " + d.CPULimit + ")"},
		{"memory-request", "NEXUS_BENCH_MEMORY_REQUEST", kindString, "memory request (default " + d.MemoryRequest + ")"},
		{"memory-limit", "NEXUS_BENCH_MEMORY_LIMIT", kindString, "memory limit (default " + d.MemoryLimit + ")"},
		{"storage-size", "NEXUS_BENCH_STORAGE_SIZE", kindString, "size of the data volume (default " + d.StorageSize + ")"},
		{"jvm-opts", "NEXUS_BENCH_JVM_OPTS", kindString, "JVM options of Nexus (default " + d.JVMOpts + ")"},
		{"image", "NEXUS_BENCH_IMAGE", kindString, "Nexus image, without the tag (default " + d.Image + ")"},
		{"image-tag", "NEXUS_BENCH_IMAGE_TAG", kindString, "Nexus image tag (default " + d.ImageTag + ")"},
		{"upstream-image", "NEXUS_BENCH_UPSTREAM_IMAGE", kindString, "image of the bench upstream registry, without the tag (default " + d.UpstreamImage + ")"},
		{"upstream-image-tag", "NEXUS_BENCH_UPSTREAM_IMAGE_TAG", kindString, "tag of the bench upstream registry image (default " + d.UpstreamImageTag + ")"},
		{"upstream-url", "NEXUS_BENCH_UPSTREAM_URL", kindString, "upstream of the proxy repository (default http://bench-upstream.<namespace>.svc.cluster.local:5000)"},
		{"anonymous", "NEXUS_BENCH_ANONYMOUS", kindBool, "enable anonymous access, --anonymous=false to disable (default true)"},
		{"hosts", "NEXUS_BENCH_HOSTS", kindString, "comma-separated hosts the NodePorts are tried on (default 127.0.0.1 and the node address)"},
		{"timeout", "NEXUS_BENCH_TIMEOUT", kindDuration, "how long up waits for Nexus, and how long the seed may run (default " + d.Timeout.String() + ")"},
		{"delete-timeout", "NEXUS_BENCH_DELETE_TIMEOUT", kindDuration, "how long down waits for the namespace to go (default " + d.DeleteTimeout.String() + ")"},
		{"secrets", "NEXUS_BENCH_SECRETS", kindString, "secrets file, outside the repository (default under $XDG_STATE_HOME/devdesk/nexus-bench)"},
		{"descriptor", "NEXUS_BENCH_DESCRIPTOR", kindString, "descriptor file (default internal/nexusbench/descriptor.json)"},
	}
}

// provisionFlags are accepted by the subcommands that provision Nexus.
func provisionFlags() []paramFlag {
	return []paramFlag{
		{"accept-eula", "NEXUS_BENCH_ACCEPT_EULA", kindConsent, "accept the Nexus Community Edition EULA on your behalf: read it first (default false; the variable counts only as the exact value yes)"},
	}
}

// restHostFlag names the flag that picks the host the admin credentials are sent to.
const restHostFlag = "rest-host"

// flagSet is the flags of one subcommand.
type flagSet struct {
	fs       *flag.FlagSet
	specs    map[string]paramFlag
	restHost *string
}

// newFlagSet registers the flags of a subcommand. It prints nothing by itself:
// the caller reports a parse error on stderr and the help on stdout.
func newFlagSet(name string) *flagSet {
	// up and provision provision Nexus (EULA); they and seed send the admin
	// credentials to the REST API (REST host).
	provisions := name == "up" || name == "provision"
	reachesREST := provisions || name == "seed" || loopbackOnly(name)
	fs := flag.NewFlagSet("nexus-bench "+name, flag.ContinueOnError)
	fs.SetOutput(io.Discard)
	fs.Usage = func() {}
	set := &flagSet{fs: fs, specs: map[string]paramFlag{}}
	specs := commonFlags()
	if provisions {
		specs = append(specs, provisionFlags()...)
	}
	for _, spec := range specs {
		set.specs[spec.name] = spec
		switch spec.kind {
		case kindString:
			fs.String(spec.name, "", spec.usage)
		case kindInt:
			fs.Int(spec.name, 0, spec.usage)
		case kindDuration:
			fs.Duration(spec.name, time.Duration(0), spec.usage)
		case kindBool, kindConsent:
			fs.Bool(spec.name, false, spec.usage)
		}
	}
	switch {
	case name == "seed" || loopbackOnly(name):
		// These refuse another host (main.go): their credentials and their images
		// always go through the loopback.
		set.restHost = fs.String(restHostFlag, "", "loopback address the REST API is reached on (default "+loopbackHost+"); "+name+" accepts a loopback address only, because its images and the admin credentials always go through "+loopbackHost)
	case reachesREST:
		set.restHost = fs.String(restHostFlag, "", "host the REST API is reached on, and so the host the admin credentials are sent to (default "+loopbackHost+"); another host sends them in clear text. It concerns the REST API only: the images always go through "+loopbackHost)
	}
	return set
}

// parse reads args. It returns flag.ErrHelp for -h and --help, and an error for
// an unknown flag, a value of the wrong type or an argument that is not a flag.
func (s *flagSet) parse(args []string) error {
	if err := s.fs.Parse(args); err != nil {
		return err
	}
	if s.fs.NArg() > 0 {
		return fmt.Errorf("unexpected argument %q", s.fs.Arg(0))
	}
	return nil
}

// printHelp writes the flags and their default to w.
func (s *flagSet) printHelp(w io.Writer) {
	s.fs.SetOutput(w)
	s.fs.PrintDefaults()
	s.fs.SetOutput(io.Discard)
}

// overlay returns getenv with every flag that was given laid over its
// NEXUS_BENCH_* variable: nexusbench.FromEnv then applies "flag, then variable,
// then default" in one place, with the same parsing and the same follow-the-
// namespace rule for the upstream URL.
func (s *flagSet) overlay(getenv func(string) string) func(string) string {
	given := map[string]string{}
	s.fs.Visit(func(f *flag.Flag) {
		spec, ok := s.specs[f.Name]
		if !ok {
			return
		}
		value := f.Value.String()
		if spec.kind == kindConsent {
			value = map[bool]string{true: "yes", false: "no"}[value == "true"]
		}
		given[spec.env] = value
	})
	return func(name string) string {
		if v, ok := given[name]; ok {
			return v
		}
		return getenv(name)
	}
}

// restHostGiven returns the --rest-host value and whether it was set.
func (s *flagSet) restHostGiven() (string, bool) {
	if s.restHost == nil {
		return "", false
	}
	given := false
	s.fs.Visit(func(f *flag.Flag) {
		if f.Name == restHostFlag {
			given = true
		}
	})
	return *s.restHost, given
}

// resolveParams returns the validated parameters of a run: defaults, then the
// NEXUS_BENCH_* variables, then the flags.
func (s *flagSet) resolveParams(getenv func(string) string) (nexusbench.Params, error) {
	p, err := nexusbench.FromEnv(nexusbench.Defaults(), s.overlay(getenv))
	if err != nil {
		return p, err
	}
	return p, p.Validate()
}

// validateRESTHost refuses what is not a host name or an IP address: a port, a
// path, a scheme, credentials or whitespace would change where the admin
// credentials go.
func validateRESTHost(host string) error {
	if host == "" || len(host) > maxHostLen {
		return fmt.Errorf("--%s: %q is not a host name or an IP address", restHostFlag, host)
	}
	if addr, ok := hostAddress(host); ok {
		if zone := addr.Zone(); zone != "" && !ipv6Zone.MatchString(zone) {
			return fmt.Errorf("--%s: %q has an unusable IPv6 zone", restHostFlag, host)
		}
		return nil
	}
	if !hostName.MatchString(host) {
		return fmt.Errorf("--%s: %q is not a host name or an IP address (no port, scheme, path or credentials)", restHostFlag, host)
	}
	return nil
}

// hostAddress parses host as an IP address, with or without the brackets of an
// IPv6 literal.
func hostAddress(host string) (netip.Addr, bool) {
	if len(host) > 1 && strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
		host = host[1 : len(host)-1]
	}
	addr, err := netip.ParseAddr(host)
	return addr, err == nil
}

// loopbackOnly tells whether a subcommand sends the admin credentials and its
// images through the loopback and nowhere else.
func loopbackOnly(name string) bool { return name == "restore-upstream" || name == "reset" }

// isLoopbackHost tells whether host stays on this machine.
func isLoopbackHost(host string) bool {
	if strings.EqualFold(host, "localhost") {
		return true
	}
	addr, ok := hostAddress(host)
	return ok && addr.Unmap().IsLoopback()
}

package main

import (
	"context"
	"errors"
	"fmt"
	"reflect"

	"github.com/anthnel/devdesk/internal/nexusbench"
)

// render prints the manifests. It builds no dependency: it contacts nothing.
func (s *session) render() int {
	out, err := nexusbench.Render(s.p)
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.stdout.Write(out); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// open resolves the secrets path and builds the runner and the store, in that
// order, before anything touches the cluster. Both are refused here when they
// cannot work: kubectl missing, a secrets path that git does not ignore.
func (s *session) open() (nexusbench.Runner, nexusbench.SecretStore, error) {
	if s.p.SecretsPath == "" {
		path, err := nexusbench.DefaultSecretsPath(s.p.Context, s.p.Namespace, s.getenv)
		if err != nil {
			return nil, nil, err
		}
		s.p.SecretsPath = path
	}
	runner, err := s.d.newRunner(s.p.Context)
	if err != nil {
		return nil, nil, err
	}
	store, err := s.d.newStore(s.p.SecretsPath)
	if err != nil {
		return nil, nil, err
	}
	return runner, store, nil
}

// doors are the two doors the seed goes through besides kubectl: the
// port-forward to the upstream and the image copier.
type doors struct {
	forwarder nexusbench.PortForwarder
	copier    nexusbench.ImageCopier
}

// openDoors builds the doors of the seed, the forwarder first. They are built
// before anything touches the cluster: a host without skopeo is refused here,
// not after the deployment.
func (s *session) openDoors() (doors, error) {
	forwarder, err := s.d.newForwarder(s.p.Context)
	if err != nil {
		return doors{}, err
	}
	copier, err := s.d.newCopier()
	if err != nil {
		return doors{}, err
	}
	return doors{forwarder: forwarder, copier: copier}, nil
}

// bounded runs fn with a context that ends after Params.Timeout, counted from
// now, so that a call over a port-forward that hangs does not hang the command.
// A call that outlasts it is a failure with its own message; a cancelled run keeps
// the plain cancellation. what names the call ("the seed"), and advice is what to
// run next.
func (s *session) bounded(what, advice string, fn func(ctx context.Context) error) error {
	ctx, cancel := s.ctx, context.CancelFunc(func() {})
	if s.p.Timeout > 0 {
		ctx, cancel = context.WithTimeout(s.ctx, s.p.Timeout)
	}
	defer cancel()
	err := fn(ctx)
	if err != nil && ctx.Err() != nil && s.ctx.Err() == nil {
		return &nexusbench.BenchError{
			Kind:  nexusbench.Deadline,
			Cause: fmt.Sprintf("%s did not finish within %s", what, s.p.Timeout),
			Check: "raise --timeout (NEXUS_BENCH_TIMEOUT) and " + advice,
			Err:   err,
		}
	}
	return err
}

// seedDeps are what the library calls that copy or read through the doors need.
func (s *session) seedDeps(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) nexusbench.SeedDeps {
	return nexusbench.SeedDeps{Runner: runner, Forwarder: d.forwarder, Copier: d.copier, Clock: s.d.clock, Store: store}
}

// runSeed runs Seed under the timeout.
func (s *session) runSeed(runner nexusbench.Runner, store nexusbench.SecretStore, d doors) (nexusbench.SeedResult, error) {
	var res nexusbench.SeedResult
	err := s.bounded("the seed", "run nexus-bench seed again: the images already copied are kept", func(ctx context.Context) (err error) {
		res, err = s.d.seed(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
		return err
	})
	if err != nil {
		return nexusbench.SeedResult{}, err
	}
	return res, nil
}

// cutUpstream scales the upstream to zero. It needs no store and no door: the
// preflight of a cut asks for what a scale needs.
func (s *session) cutUpstream() int {
	runner, _, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpCut); err != nil {
		return s.fail(err)
	}
	if err := s.d.cutUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// restoreUpstream brings a cut upstream back. It writes no descriptor.
func (s *session) restoreUpstream() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpRestore); err != nil {
		return s.fail(err)
	}
	err = s.bounded("the restore", "run `mise run nexus-bench:restore-upstream` again", func(ctx context.Context) error {
		return s.d.restoreUpstream(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
	})
	if err != nil {
		return s.fail(err)
	}
	return exitOK
}

// reset puts the data set back to its initial state. Reset runs its own
// preflight; the descriptor of the previous run is read before anything is
// deleted and written again after a reset that succeeded, with the hosts of the
// previous one (the preflight of a reset reads no node).
func (s *session) reset() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	prev, err := s.previousDescriptor()
	if err != nil {
		return s.fail(err)
	}
	var provisioned nexusbench.ProvisionResult
	var seeded nexusbench.SeedResult
	err = s.bounded("the reset", "run `mise run nexus-bench:reset` again: it starts over", func(ctx context.Context) (err error) {
		provisioned, seeded, err = s.d.reset(ctx, s.seedDeps(runner, store, d), s.restURL(), s.p, s.stdout)
		return err
	})
	if errors.Is(err, context.Canceled) {
		// The library returns the cancellation as is, and a reset stopped after its
		// first deletion leaves a half-deleted data set.
		_, _ = fmt.Fprintln(s.stderr, "cancelled; the data set may be half deleted, run `mise run nexus-bench:reset` again: it starts over")
		return exitFailure
	}
	if err != nil {
		return s.fail(err)
	}
	return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
}

// up deploys the bench and the upstream, provisions Nexus, seeds the data set
// and only then writes the descriptor (D-J). Deploy runs the preflight of up
// itself. An upstream URL the bench did not deploy is left alone: nothing is
// scaled or seeded, and the data set is described as empty.
func (s *session) up() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	seeds := s.p.UpstreamIsBench()
	var d doors
	if seeds {
		if d, err = s.openDoors(); err != nil {
			return s.fail(err)
		}
	}
	s.warnIfClearText()
	deployed, err := s.d.deploy(s.ctx, runner, s.d.newProber(), s.d.clock, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	cut := false
	if seeds {
		if cut, err = s.foundCut(runner); err != nil {
			return s.fail(err)
		}
		if err := s.d.ensureUpstream(s.ctx, runner, s.d.clock, s.p, s.stdout); err != nil {
			return s.fail(err)
		}
	}
	provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	if cut {
		if err := s.d.unblockProxy(s.ctx, store, s.restURL(), s.p, s.stdout); err != nil {
			return s.fail(retryRestore(err))
		}
	}
	var seeded nexusbench.SeedResult
	if seeds {
		if seeded, err = s.runSeed(runner, store, d); err != nil {
			return s.fail(err)
		}
	} else {
		_, _ = fmt.Fprintln(s.stdout, "seed: skipped, NEXUS_BENCH_UPSTREAM_URL points at an upstream the bench did not deploy, so there is nothing to fill")
	}
	return s.writeDescriptor(deployed, provisioned, seeded)
}

// retryRestore tells, in the check of a BenchError, that the proxy is still
// blocked and that a second up will not unblock it: the upstream is back by now,
// so the second up finds it ready. Another error is returned as it is.
func retryRestore(err error) error {
	var be *nexusbench.BenchError
	if !errors.As(err, &be) {
		return err
	}
	return &nexusbench.BenchError{
		Kind:  be.Kind,
		Cause: be.Cause,
		Check: be.Check + "; the upstream is back but docker-proxy is still blocked, and a second up will not retry that: run `mise run nexus-bench:restore-upstream`",
		Err:   be.Err,
	}
}

// foundCut reads the upstream before EnsureUpstream brings it back, and tells
// whether it was cut: the proxy then needs to be unblocked (D-Q). The proxy can
// only be unblocked through the loopback; with another REST host, up stops here,
// before it brings the upstream back, because a refusal later would leave a proxy
// that stays blocked (a second up finds the upstream ready).
func (s *session) foundCut(runner nexusbench.Runner) (bool, error) {
	state, err := s.d.readUpstream(s.ctx, runner, s.p)
	if err != nil {
		return false, err
	}
	if state != nexusbench.UpstreamCut {
		return false, nil
	}
	if !nexusbench.IsLoopbackRESTHost(s.restHost) {
		return false, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the upstream is cut and its proxy can only be put back in service through 127.0.0.1, not through %s", s.restHost),
			Check: "run `mise run nexus-bench:restore-upstream` on the machine that runs the bench, then up again",
		}
	}
	return true, nil
}

// provision provisions a bench that is already running.
func (s *session) provision() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	s.warnIfClearText()
	pre, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpProvision)
	if err != nil {
		return s.fail(err)
	}
	provisioned, err := s.d.provision(s.ctx, s.restURL(), s.d.newInitial(runner, s.p.Namespace), store, s.p, s.stdout)
	if err != nil {
		return s.fail(err)
	}
	return s.writeDescriptor(nexusbench.DeployResult{NodeIP: pre.NodeIP}, provisioned, s.keptDataset())
}

// keptDataset returns the data set of the code when the descriptor on disk is the
// descriptor of the same bench (namespace, context and upstream URL unchanged) and
// lists exactly that data set: the data set is fixed in the code, so what the file
// holds is compared to it and never copied. A file that disagrees, or is of another
// bench, counts as no data set, and the command says so. A descriptor that cannot
// be read (none, or schema 1), or that lists no image, has nothing to keep.
func (s *session) keptDataset() nexusbench.SeedResult {
	prev, err := nexusbench.LoadDescriptor(s.descriptorPath())
	if err != nil || len(prev.Dataset) == 0 {
		return nexusbench.SeedResult{}
	}
	code := nexusbench.SeedResult{Images: nexusbench.Dataset()}
	want := nexusbench.BuildDescriptor(s.p, nexusbench.DeployResult{}, nexusbench.ProvisionResult{}, code).Dataset
	if prev.Namespace == s.p.Namespace && prev.KubeContext == s.p.Context && prev.Upstream.URL == s.p.UpstreamURL &&
		reflect.DeepEqual(prev.Dataset, want) {
		return code
	}
	line := "provision: the descriptor now lists no data set"
	if s.p.UpstreamIsBench() {
		line += "; run mise run nexus-bench:seed"
	}
	_, _ = fmt.Fprintln(s.stdout, line)
	return nexusbench.SeedResult{}
}

// seed puts the data set in a bench that up already provisioned, then writes the
// descriptor again. Seed has no data of its own about Nexus: the version, the
// edition, the EULA consent and the hosts (and so the URLs that depend on them)
// come from the descriptor of the previous run, which is read before anything is
// copied. The preflight of a seed does not read the node, so it has no address to
// give.
func (s *session) seed() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	d, err := s.openDoors()
	if err != nil {
		return s.fail(err)
	}
	s.warnIfClearText()
	prev, err := s.previousDescriptor()
	if err != nil {
		return s.fail(err)
	}
	if _, err := s.d.preflight(s.ctx, runner, s.p, nexusbench.OpSeed); err != nil {
		return s.fail(err)
	}
	seeded, err := s.runSeed(runner, store, d)
	if err != nil {
		return s.fail(err)
	}
	provisioned := nexusbench.ProvisionResult{NexusVersion: prev.NexusVersion, Edition: prev.Edition, EULAAccepted: prev.EULAAccepted}
	return s.writeDescriptor(nexusbench.DeployResult{ReachableHosts: prev.Hosts}, provisioned, seeded)
}

// previousDescriptor reads the descriptor of the previous run. Without a readable
// descriptor of schema 2 (missing, schema 1, not JSON), or with the descriptor of
// another bench (namespace or context), the bench was not provisioned by this
// build for these parameters, and the answer is to run up.
func (s *session) previousDescriptor() (nexusbench.Descriptor, error) {
	path := s.descriptorPath()
	prev, err := nexusbench.LoadDescriptor(path)
	var be *nexusbench.BenchError
	switch {
	case err == nil:
	case errors.As(err, &be):
		return prev, err
	default:
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: "there is no readable descriptor of a provisioned bench (" + err.Error() + ")",
			Check: "run `mise run nexus-bench:up` first: the seed completes the descriptor that up writes",
			Err:   err,
		}
	}
	if prev.Namespace != s.p.Namespace || prev.KubeContext != s.p.Context {
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the descriptor %s describes namespace %q on context %q, not namespace %q on context %q", path, prev.Namespace, prev.KubeContext, s.p.Namespace, s.p.Context),
			Check: "run `mise run nexus-bench:up` for this bench first: the seed completes the descriptor that up writes",
		}
	}
	if err := nexusbench.ValidateDescriptorHosts(prev.Hosts); err != nil {
		return prev, &nexusbench.BenchError{
			Kind:  nexusbench.Unclassified,
			Cause: fmt.Sprintf("the descriptor %s cannot be trusted: %s", path, err),
			Check: "run `mise run nexus-bench:up` for this bench first: it writes the descriptor again",
		}
	}
	return prev, nil
}

// down deletes the bench namespace. The descriptor is left alone: it is the
// versioned description of the bench, not part of one instance.
func (s *session) down() int {
	runner, store, err := s.open()
	if err != nil {
		return s.fail(err)
	}
	if err := s.d.destroy(s.ctx, runner, s.d.clock, store, s.p, s.stdout); err != nil {
		return s.fail(err)
	}
	return exitOK
}

// descriptorPath is where the descriptor is read and written.
func (s *session) descriptorPath() string {
	if s.p.DescriptorPath != "" {
		return s.p.DescriptorPath
	}
	return nexusbench.DescriptorPath()
}

// writeDescriptor writes the descriptor of a bench that was provisioned and, for
// up and seed, seeded. It is called after a step that succeeded only: a partial
// result is never described.
func (s *session) writeDescriptor(deployed nexusbench.DeployResult, provisioned nexusbench.ProvisionResult, seeded nexusbench.SeedResult) int {
	path := s.descriptorPath()
	if err := nexusbench.WriteDescriptor(path, nexusbench.BuildDescriptor(s.p, deployed, provisioned, seeded)); err != nil {
		return s.fail(err)
	}
	_, _ = fmt.Fprintf(s.stdout, "nexus-bench: descriptor written to %s\n", path)
	if !describesDefaultBench(s.p) {
		s.warn("descriptor.json now describes a non-default bench; do not commit it")
	}
	return exitOK
}

// describesDefaultBench tells whether p is the bench the versioned descriptor
// describes. The timeouts, the paths and the EULA consent do not change what
// the bench is, so they are left out.
func describesDefaultBench(p nexusbench.Params) bool {
	normalize := func(p nexusbench.Params) nexusbench.Params {
		p.Timeout, p.DeleteTimeout = 0, 0
		p.SecretsPath, p.DescriptorPath = "", ""
		p.AcceptEULA = false
		if len(p.Hosts) == 0 {
			p.Hosts = nil
		}
		return p
	}
	return reflect.DeepEqual(normalize(p), normalize(nexusbench.Defaults()))
}
