		r.h.env["NEXUS_BENCH_CONTEXT"], r.h.env["NEXUS_BENCH_NAMESPACE"], r.h.env["NEXUS_BENCH_HTTP_NODEPORT"] = "ctx-env", "nb-env", "31007"
