			if code != 2 {
				t.Errorf("exit code = %d, want 2", code)
			}
			if stdout != "" || strings.TrimSpace(stderr) == "" {
				t.Errorf("stdout %q, stderr %q: want an empty stdout and a message", stdout, stderr)
			}
			requireClean(t, stderr)
			r.h.requireNoCalls()
			r.requireRefusedBeforeRecord()
		})
	}
}

